<?php

if ( ! defined( 'ABSPATH' ) ) {
	exit;
}

final class CGR_Admin {
	private $database;
	private $api;
	private $sync;
	private $importer;

	public function __construct( CGR_Database $database, CGR_Google_API $api, CGR_Sync $sync, CGR_Importer $importer ) {
		$this->database = $database;
		$this->api      = $api;
		$this->sync     = $sync;
		$this->importer = $importer;
		add_action( 'admin_menu', array( $this, 'register_menu' ) );
		add_action( 'admin_enqueue_scripts', array( $this, 'enqueue_assets' ) );
		foreach ( array( 'save_settings', 'add_location', 'delete_location', 'save_display_settings', 'add_review', 'import_csv', 'export_reviews', 'delete_reviews', 'delete_all_reviews', 'remove_duplicates', 'sync_place', 'sync_outscraper', 'test_place' ) as $action ) {
			add_action( 'admin_post_cgr_' . $action, array( $this, $action ) );
		}
	}

	public function register_menu() {
		add_menu_page( __( 'Google Reviews', 'calico-google-reviews' ), __( 'Google Reviews', 'calico-google-reviews' ), 'manage_options', 'cgr-reviews', array( $this, 'render_reviews' ), 'dashicons-star-filled', 58 );
		add_submenu_page( 'cgr-reviews', __( 'Reviews', 'calico-google-reviews' ), __( 'Reviews', 'calico-google-reviews' ), 'manage_options', 'cgr-reviews', array( $this, 'render_reviews' ) );
		add_submenu_page( 'cgr-reviews', __( 'Review Sources', 'calico-google-reviews' ), __( 'Sources', 'calico-google-reviews' ), 'manage_options', 'cgr-sources', array( $this, 'render_sources' ) );
		add_submenu_page( 'cgr-reviews', __( 'Manual Import', 'calico-google-reviews' ), __( 'Manual Import', 'calico-google-reviews' ), 'manage_options', 'cgr-import', array( $this, 'render_import' ) );
		add_submenu_page( 'cgr-reviews', __( 'Display Reviews', 'calico-google-reviews' ), __( 'Display', 'calico-google-reviews' ), 'manage_options', 'cgr-display', array( $this, 'render_display' ) );
		add_submenu_page( 'cgr-reviews', __( 'Setup Instructions', 'calico-google-reviews' ), __( 'Instructions', 'calico-google-reviews' ), 'manage_options', 'cgr-instructions', array( $this, 'render_instructions' ) );
	}

	public function enqueue_assets() {
		$screen = function_exists( 'get_current_screen' ) ? get_current_screen() : null;
		if ( $screen && false !== strpos( $screen->id, 'cgr-' ) ) {
			wp_enqueue_style( 'cgr-admin', CGR_URL . 'assets/css/admin.css', array(), CGR_VERSION );
			wp_enqueue_script( 'cgr-admin', CGR_URL . 'assets/js/admin.js', array(), CGR_VERSION, true );
			wp_localize_script( 'cgr-admin', 'cgrAdmin', array( 'copied' => __( 'Copied!', 'calico-google-reviews' ) ) );
		}
	}

	public function render_reviews() {
		$this->guard();
		$search = isset( $_GET['s'] ) ? sanitize_text_field( wp_unslash( $_GET['s'] ) ) : '';
		$source = isset( $_GET['source'] ) ? sanitize_key( wp_unslash( $_GET['source'] ) ) : '';
		$rating = isset( $_GET['rating'] ) ? absint( $_GET['rating'] ) : 0;
		$location_id = isset( $_GET['location'] ) ? sanitize_key( wp_unslash( $_GET['location'] ) ) : '';
		$location_keys = $this->api->get_location_keys( $location_id );
		$page   = isset( $_GET['paged'] ) ? max( 1, absint( $_GET['paged'] ) ) : 1;
		$result = $this->database->query_reviews( compact( 'search', 'source', 'rating', 'location_keys', 'page' ) );
		$pages  = max( 1, (int) ceil( $result['total'] / 20 ) );
		$duplicates = $this->database->duplicate_report();
		$this->header( __( 'Reviews', 'calico-google-reviews' ), sprintf( __( '%s stored reviews', 'calico-google-reviews' ), number_format_i18n( $this->database->count_all() ) ) );
		?>
		<form method="get" class="cgr-filters"><input type="hidden" name="page" value="cgr-reviews"><input type="search" name="s" value="<?php echo esc_attr( $search ); ?>" placeholder="<?php esc_attr_e( 'Search reviewer or text', 'calico-google-reviews' ); ?>"><select name="location"><option value=""><?php esc_html_e( 'All locations', 'calico-google-reviews' ); ?></option><?php foreach ( $this->api->get_locations() as $id => $location ) : ?><option value="<?php echo esc_attr( $id ); ?>" <?php selected( $location_id, $id ); ?>><?php echo esc_html( $location['location_name'] ); ?></option><?php endforeach; ?></select><select name="source"><option value=""><?php esc_html_e( 'All sources', 'calico-google-reviews' ); ?></option><?php foreach ( array( 'places', 'outscraper', 'business', 'csv', 'manual' ) as $item ) : ?><option value="<?php echo esc_attr( $item ); ?>" <?php selected( $source, $item ); ?>><?php echo esc_html( $this->source_label( $item ) ); ?></option><?php endforeach; ?></select><select name="rating"><option value="0"><?php esc_html_e( 'All ratings', 'calico-google-reviews' ); ?></option><?php for ( $stars = 5; $stars >= 1; $stars-- ) : ?><option value="<?php echo esc_attr( $stars ); ?>" <?php selected( $rating, $stars ); ?>><?php echo esc_html( $stars . ' stars' ); ?></option><?php endfor; ?></select><button class="button"><?php esc_html_e( 'Filter', 'calico-google-reviews' ); ?></button></form>
		<form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="cgr_delete_reviews"><?php wp_nonce_field( 'cgr_delete_reviews' ); ?><div class="cgr-table-wrap"><table class="widefat striped cgr-review-table"><thead><tr><td class="check-column"><input type="checkbox" class="cgr-check-all"></td><th><?php esc_html_e( 'Reviewer', 'calico-google-reviews' ); ?></th><th><?php esc_html_e( 'Rating', 'calico-google-reviews' ); ?></th><th><?php esc_html_e( 'Review', 'calico-google-reviews' ); ?></th><th><?php esc_html_e( 'Source', 'calico-google-reviews' ); ?></th><th><?php esc_html_e( 'Date', 'calico-google-reviews' ); ?></th></tr></thead><tbody>
		<?php if ( empty( $result['items'] ) ) : ?><tr><td colspan="6"><?php esc_html_e( 'No matching reviews.', 'calico-google-reviews' ); ?></td></tr><?php endif; ?>
		<?php foreach ( $result['items'] as $review ) : ?><tr><th class="check-column"><input type="checkbox" name="review_ids[]" value="<?php echo esc_attr( $review['id'] ); ?>"></th><td><strong><?php echo esc_html( $review['reviewer_name'] ); ?></strong></td><td><span class="cgr-admin-stars"><?php echo esc_html( str_repeat( '★', (int) $review['rating'] ) ); ?></span></td><td><?php echo esc_html( wp_trim_words( $review['review_text'], 24 ) ); ?></td><td><span class="cgr-source-badge"><?php echo esc_html( $this->source_label( $review['source'] ) ); ?></span></td><td><?php echo esc_html( $review['create_time'] ? mysql2date( get_option( 'date_format' ), $review['create_time'] ) : '—' ); ?></td></tr><?php endforeach; ?></tbody></table></div><p><button class="button" type="submit" onclick="return confirm('<?php echo esc_js( __( 'Delete the selected reviews?', 'calico-google-reviews' ) ); ?>')"><?php esc_html_e( 'Delete selected', 'calico-google-reviews' ); ?></button></p></form>
		<?php if ( $pages > 1 ) : ?><div class="tablenav"><div class="tablenav-pages"><?php echo wp_kses_post( paginate_links( array( 'base' => add_query_arg( 'paged', '%#%' ), 'current' => $page, 'total' => $pages ) ) ); ?></div></div><?php endif; ?>
		<div class="cgr-two-column cgr-review-tools">
		<section class="cgr-card"><h2><?php esc_html_e( 'Remove duplicate reviews', 'calico-google-reviews' ); ?></h2><p><?php echo esc_html( sprintf( _n( '%d suspected duplicate is ready to remove.', '%d suspected duplicates are ready to remove.', $duplicates['duplicates'], 'calico-google-reviews' ), $duplicates['duplicates'] ) ); ?></p><p><?php esc_html_e( 'Matching prioritizes external review IDs, then reviewer name, rating, review text, and date. Cleanup keeps the newest, most complete record, including replies, photos, and source links.', 'calico-google-reviews' ); ?></p><p><a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-import#cgr-export-reviews' ) ); ?>"><?php esc_html_e( 'Export all reviews before cleanup →', 'calico-google-reviews' ); ?></a></p><?php if ( $duplicates['duplicates'] ) : ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="cgr_remove_duplicates"><?php wp_nonce_field( 'cgr_remove_duplicates' ); ?><button class="button" type="submit" onclick="return confirm('<?php echo esc_js( __( 'Remove all detected duplicate reviews? Export a backup first if you may need to restore them.', 'calico-google-reviews' ) ); ?>')"><?php esc_html_e( 'Remove duplicates', 'calico-google-reviews' ); ?></button></form><?php else : ?><p><strong><?php esc_html_e( 'No duplicates detected.', 'calico-google-reviews' ); ?></strong></p><?php endif; ?></section>
		<section class="cgr-card cgr-danger-zone"><h2><?php esc_html_e( 'Delete all reviews', 'calico-google-reviews' ); ?></h2><p><strong><?php esc_html_e( 'Warning: This permanently deletes every stored review. The plugin does not create an automatic backup.', 'calico-google-reviews' ); ?></strong></p><p><a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-import#cgr-export-reviews' ) ); ?>"><?php esc_html_e( 'Export all reviews and read backup instructions →', 'calico-google-reviews' ); ?></a></p><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="cgr_delete_all_reviews"><?php wp_nonce_field( 'cgr_delete_all_reviews' ); ?><button class="button cgr-delete-all" type="submit" onclick="return confirm('<?php echo esc_js( __( 'Permanently delete ALL reviews? There is no automatic backup and this cannot be undone.', 'calico-google-reviews' ) ); ?>')"><?php esc_html_e( 'Delete ALL reviews', 'calico-google-reviews' ); ?></button></form></section>
		</div><script>document.addEventListener('change',function(e){if(e.target.classList.contains('cgr-check-all')){document.querySelectorAll('input[name="review_ids[]"]').forEach(function(i){i.checked=e.target.checked;});}});</script>
		<?php $this->footer();
	}

	public function render_sources() {
		$this->guard();
		$locations          = $this->api->get_locations();
		$location_id        = isset( $_GET['location'] ) ? sanitize_key( wp_unslash( $_GET['location'] ) ) : $this->api->get_default_location_id();
		if ( ! isset( $locations[ $location_id ] ) ) { $location_id = $this->api->get_default_location_id(); }
		$s                  = $this->api->get_location_settings( $location_id );
		$review_request_url = $this->api->get_review_request_url( $location_id );
		$stored_count       = $this->database->count_display_reviews( 'all', array(), false, $this->api->get_location_keys( $location_id ) );
		$this->header( __( 'Review Sources', 'calico-google-reviews' ), __( 'Choose a primary source and configure any providers you want to use.', 'calico-google-reviews' ) );
		?>
		<nav class="cgr-location-tabs" aria-label="<?php esc_attr_e( 'Business locations', 'calico-google-reviews' ); ?>"><?php foreach ( $locations as $id => $location ) : ?><a class="button <?php echo $id === $location_id ? 'button-primary' : ''; ?>" href="<?php echo esc_url( add_query_arg( array( 'page' => 'cgr-sources', 'location' => $id ), admin_url( 'admin.php' ) ) ); ?>"><?php echo esc_html( $location['location_name'] ); ?></a><?php endforeach; ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'cgr_add_location' ); ?><input type="hidden" name="action" value="cgr_add_location"><input required name="location_name" placeholder="<?php esc_attr_e( 'New location name', 'calico-google-reviews' ); ?>"><button class="button"><?php esc_html_e( 'Add location', 'calico-google-reviews' ); ?></button></form></nav>
		<nav class="cgr-help-links" aria-label="<?php esc_attr_e( 'Source setup guides', 'calico-google-reviews' ); ?>"><strong><?php esc_html_e( 'Setup guides:', 'calico-google-reviews' ); ?></strong> <a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-instructions#cgr-instructions-places' ) ); ?>"><?php esc_html_e( 'Google Places API', 'calico-google-reviews' ); ?></a> <a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-instructions#cgr-instructions-outscraper' ) ); ?>"><?php esc_html_e( 'Outscraper API', 'calico-google-reviews' ); ?></a></nav>
		<form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><?php wp_nonce_field( 'cgr_save_settings' ); ?><input type="hidden" name="action" value="cgr_save_settings"><input type="hidden" name="location_id" value="<?php echo esc_attr( $location_id ); ?>">
		<section class="cgr-card"><h2><?php esc_html_e( 'Location profile', 'calico-google-reviews' ); ?></h2><table class="form-table"><tr><th><label for="cgr-location-name"><?php esc_html_e( 'Location name', 'calico-google-reviews' ); ?></label></th><td><input id="cgr-location-name" class="regular-text" required name="location_name" value="<?php echo esc_attr( $s['location_name'] ); ?>"><p class="description"><?php esc_html_e( 'This label appears in the Elementor Location selector.', 'calico-google-reviews' ); ?></p></td></tr></table></section>
		<section class="cgr-card"><h2><?php esc_html_e( 'Location status', 'calico-google-reviews' ); ?></h2><div class="cgr-status-grid"><p><strong><?php esc_html_e( 'Stored reviews', 'calico-google-reviews' ); ?></strong><span><?php echo esc_html( number_format_i18n( $stored_count ) ); ?></span></p><p><strong><?php esc_html_e( 'Google Places API last sync', 'calico-google-reviews' ); ?></strong><span><?php echo esc_html( $s['last_sync'] ? mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $s['last_sync'] ) : __( 'Not yet synchronized', 'calico-google-reviews' ) ); ?></span></p><p><strong><?php esc_html_e( 'Outscraper API last sync', 'calico-google-reviews' ); ?></strong><span><?php echo esc_html( $s['outscraper_last_sync'] ? mysql2date( get_option( 'date_format' ) . ' ' . get_option( 'time_format' ), $s['outscraper_last_sync'] ) : __( 'Not yet synchronized', 'calico-google-reviews' ) ); ?></span></p></div><?php if ( $s['last_error'] ) : ?><p class="cgr-error"><strong><?php esc_html_e( 'Last error:', 'calico-google-reviews' ); ?></strong> <?php echo esc_html( $s['last_error'] ); ?></p><?php endif; ?></section>
		<section class="cgr-card"><h2><?php esc_html_e( 'Primary display source', 'calico-google-reviews' ); ?></h2><div class="cgr-mode-grid"><?php foreach ( array( 'place' => array( 'Google Places API rolling collection', 'Official Google Places API sample, retained and checked every seven days.' ), 'outscraper' => array( 'Outscraper API full import', 'Use Outscraper to scrape all past reviews instantly, and schedule new pulls. 500 free credits per month available (pull 1 review = 1 credit), so most accounts will pay nothing.' ) ) as $key => $label ) : ?><label class="cgr-mode"><input type="radio" name="mode" value="<?php echo esc_attr( $key ); ?>" <?php checked( $s['mode'], $key ); ?>><span><strong><?php echo esc_html( $label[0] ); ?></strong><small><?php echo esc_html( $label[1] ); ?></small></span></label><?php endforeach; ?></div></section>
		<section class="cgr-card"><h2><?php esc_html_e( 'Google Places API', 'calico-google-reviews' ); ?></h2><p class="description"><?php esc_html_e( 'Limit 5 initial reviews, good for testing environments, no backlog review pulling.', 'calico-google-reviews' ); ?></p><p><a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-instructions#cgr-instructions-places' ) ); ?>"><?php esc_html_e( 'View Google Places API setup and Place ID instructions →', 'calico-google-reviews' ); ?></a></p><table class="form-table"><tr><th><label for="cgr-place-id">Place ID</label></th><td><input id="cgr-place-id" class="regular-text" name="place_id" value="<?php echo esc_attr( $s['place_id'] ); ?>"></td></tr><tr><th><label for="cgr-maps-key">API key</label></th><td><input id="cgr-maps-key" class="regular-text" type="password" name="maps_api_key" autocomplete="new-password" placeholder="<?php echo esc_attr( $s['maps_api_key_enc'] ? __( 'Saved — leave blank to keep', 'calico-google-reviews' ) : '' ); ?>"></td></tr><tr><th><?php esc_html_e( 'Rolling collection', 'calico-google-reviews' ); ?></th><td><label><input type="checkbox" name="rolling_collection" value="yes" <?php checked( $s['rolling_collection'], 'yes' ); ?>> <?php esc_html_e( 'Store newly exposed reviews every seven days', 'calico-google-reviews' ); ?></label></td></tr><tr><th><label for="cgr-review-request-override"><?php esc_html_e( 'Official review-request link', 'calico-google-reviews' ); ?></label></th><td><input id="cgr-review-request-override" class="large-text" type="url" name="review_request_url" value="<?php echo esc_attr( $s['review_request_url'] ); ?>" placeholder="https://g.page/r/…/review"><p class="description"><?php esc_html_e( 'Optional. Paste the official link from your Business Profile to override the Place ID link generated below.', 'calico-google-reviews' ); ?></p></td></tr><tr><th><label for="cgr-review-request-link"><?php esc_html_e( 'Review-request link', 'calico-google-reviews' ); ?></label></th><td><div class="cgr-copy-row"><input id="cgr-review-request-link" class="large-text" type="url" readonly value="<?php echo esc_attr( $review_request_url ); ?>"><button type="button" class="button cgr-copy-button" data-copy-target="#cgr-review-request-link"><?php esc_html_e( 'Copy Link', 'calico-google-reviews' ); ?></button><a id="cgr-review-request-test" class="button" href="<?php echo esc_url( $review_request_url ); ?>" target="_blank" rel="noopener noreferrer"><?php esc_html_e( 'Test Link', 'calico-google-reviews' ); ?></a></div><p class="description"><?php esc_html_e( 'Generated automatically from the Place ID unless an official link is supplied.', 'calico-google-reviews' ); ?></p></td></tr></table></section>
		<section class="cgr-card"><h2><?php esc_html_e( 'Outscraper API', 'calico-google-reviews' ); ?></h2><p class="description"><?php esc_html_e( 'Use Outscraper to scrape all past reviews instantly, and schedule new pulls. 500 free credits per month available (pull 1 review = 1 credit), so most accounts will pay nothing.', 'calico-google-reviews' ); ?></p><p><a href="<?php echo esc_url( admin_url( 'admin.php?page=cgr-instructions#cgr-instructions-outscraper' ) ); ?>"><?php esc_html_e( 'View Outscraper API and Place ID instructions →', 'calico-google-reviews' ); ?></a></p><table class="form-table"><tr><th><label for="cgr-outs-query"><?php esc_html_e( 'Place ID', 'calico-google-reviews' ); ?></label></th><td><input id="cgr-outs-query" class="large-text" name="outscraper_query" value="<?php echo esc_attr( $s['outscraper_query'] ); ?>" placeholder="ChIJ…"></td></tr><tr><th><label for="cgr-outs-key">API key</label></th><td><input id="cgr-outs-key" class="regular-text" type="password" name="outscraper_api_key" autocomplete="new-password" placeholder="<?php echo esc_attr( $s['outscraper_api_key_enc'] ? __( 'Saved — leave blank to keep', 'calico-google-reviews' ) : '' ); ?>"></td></tr><tr><th><label for="cgr-outs-limit">Review limit</label></th><td><input id="cgr-outs-limit" type="number" min="0" max="10000" name="outscraper_limit" value="<?php echo esc_attr( $s['outscraper_limit'] ); ?>"><p class="description"><?php esc_html_e( 'Set to very high or zero to scrape all past reviews for setup, then back down to a reasonable number to scan and pull new reviews. Example: if you normally get 20 reviews per week, set it to 30.', 'calico-google-reviews' ); ?></p></td></tr><tr><th><label for="cgr-outs-schedule"><?php esc_html_e( 'Check for new reviews', 'calico-google-reviews' ); ?></label></th><td><select id="cgr-outs-schedule" name="outscraper_schedule"><option value="weekly" <?php selected( $s['outscraper_schedule'], 'weekly' ); ?>><?php esc_html_e( 'Weekly — recommended/default', 'calico-google-reviews' ); ?></option><option value="daily" <?php selected( $s['outscraper_schedule'], 'daily' ); ?>><?php esc_html_e( 'Daily — medium API usage', 'calico-google-reviews' ); ?></option><option value="hourly" <?php selected( $s['outscraper_schedule'], 'hourly' ); ?>><?php esc_html_e( 'Hourly — high API usage and potential cost', 'calico-google-reviews' ); ?></option></select><p class="description cgr-warning"><?php esc_html_e( 'Warning: Hourly and daily pulls may lead to charges with Outscraper. Set to weekly to avoid charges and stay under the 500-credit limit.', 'calico-google-reviews' ); ?></p></td></tr></table></section>
		<?php submit_button( __( 'Save source settings', 'calico-google-reviews' ) ); ?></form>
		<div class="cgr-action-row"><?php $this->action_form( 'cgr_test_place', __( 'Test Google Places API connection', 'calico-google-reviews' ), false, array( 'location_id' => $location_id ) ); $this->action_form( 'cgr_sync_place', __( 'Collect Google Places API reviews now', 'calico-google-reviews' ), true, array( 'location_id' => $location_id ) ); $this->action_form( 'cgr_sync_outscraper', __( 'Import from Outscraper API now', 'calico-google-reviews' ), true, array( 'location_id' => $location_id ) ); ?></div>
		<?php if ( count( $locations ) > 1 ) : ?><section class="cgr-card cgr-danger-zone"><h2><?php esc_html_e( 'Delete this location', 'calico-google-reviews' ); ?></h2><p><?php esc_html_e( 'This removes the location profile. Stored reviews remain available under All locations until deleted from the Reviews page.', 'calico-google-reviews' ); ?></p><?php $this->action_form( 'cgr_delete_location', __( 'Delete location', 'calico-google-reviews' ), false, array( 'location_id' => $location_id ), __( 'Delete this location profile? Its stored reviews will remain available under All locations.', 'calico-google-reviews' ) ); ?></section><?php endif; ?>
		<?php $this->footer();
	}

	public function render_import() {
		$this->guard();
		$locations = $this->api->get_locations();
		$this->header( __( 'Manual Import', 'calico-google-reviews' ), __( 'Add reviews manually, import CSV files, or export a complete backup.', 'calico-google-reviews' ) );
		?>
