	public function save_display_settings() {
		$this->authorize( 'cgr_save_display_settings' );
		$ratings = isset( $_POST['visible_ratings'] ) ? array_values( array_intersect( array( 1, 2, 3, 4, 5 ), array_map( 'absint', (array) $_POST['visible_ratings'] ) ) ) : array();
		if ( empty( $ratings ) ) { $ratings = array( 5 ); }
		$this->api->update_settings(
			array(
				'visible_ratings'     => $ratings,
				'require_review_text' => isset( $_POST['require_review_text'] ) ? 'yes' : 'no',
				'truncate_reviews'    => isset( $_POST['truncate_reviews'] ) ? 'yes' : 'no',
				'review_word_limit'   => isset( $_POST['review_word_limit'] ) ? max( 5, min( 500, absint( $_POST['review_word_limit'] ) ) ) : 40,
				'read_more_label'     => isset( $_POST['read_more_label'] ) && '' !== trim( wp_unslash( $_POST['read_more_label'] ) ) ? sanitize_text_field( wp_unslash( $_POST['read_more_label'] ) ) : __( 'Read more…', 'calico-google-reviews' ),
			)
		);
		$this->redirect( 'cgr-display', 'success', __( 'Display settings saved.', 'calico-google-reviews' ) );
	}

