alico-google-reviews' ), esc_url( 'https://support.google.com/business/answer/16816815' ) ) ); ?></li><li><?php esc_html_e( 'Use Copy Link to share it or Test Link to verify it.', 'calico-google-reviews' ); ?></li></ol><p><?php esc_html_e( 'Google returns a small current sample. Rolling collection retains newly exposed reviews but cannot guarantee a complete history.', 'calico-google-reviews' ); ?></p></section>
