	public function save_settings() {
		$this->authorize( 'cgr_save_settings' );
		$location_id = isset( $_POST['location_id'] ) ? sanitize_key( wp_unslash( $_POST['location_id'] ) ) : $this->api->get_default_location_id();
		$current   = $this->api->get_location_settings( $location_id );
		$mode      = isset( $_POST['mode'] ) ? sanitize_key( wp_unslash( $_POST['mode'] ) ) : 'place';
		$query     = isset( $_POST['outscraper_query'] ) ? sanitize_text_field( wp_unslash( $_POST['outscraper_query'] ) ) : '';
		$schedule  = isset( $_POST['outscraper_schedule'] ) ? sanitize_key( wp_unslash( $_POST['outscraper_schedule'] ) ) : 'weekly';
		if ( ! in_array( $mode, array( 'place', 'outscraper' ), true ) ) { $mode = 'place'; }
		if ( ! in_array( $schedule, array( 'hourly', 'daily', 'weekly' ), true ) ) { $schedule = 'weekly'; }
		if ( preg_match( '#^https?://#i', $query ) ) {
			$this->redirect( 'cgr-sources', 'error', __( 'Enter a Place ID instead of a URL.', 'calico-google-reviews' ), array( 'location' => $location_id ) );
		}
		$changes = array( 'location_name' => isset( $_POST['location_name'] ) ? sanitize_text_field( wp_unslash( $_POST['location_name'] ) ) : $current['location_name'], 'mode' => $mode, 'place_id' => isset( $_POST['place_id'] ) ? sanitize_text_field( wp_unslash( $_POST['place_id'] ) ) : '', 'review_request_url' => isset( $_POST['review_request_url'] ) ? esc_url_raw( wp_unslash( $_POST['review_request_url'] ) ) : '', 'rolling_collection' => isset( $_POST['rolling_collection'] ) ? 'yes' : 'no', 'outscraper_query' => $query, 'outscraper_limit' => isset( $_POST['outscraper_limit'] ) ? max( 0, min( 10000, absint( $_POST['outscraper_limit'] ) ) ) : 100, 'outscraper_schedule' => $schedule );
		foreach ( array( 'maps_api_key' => 'maps_api_key_enc', 'outscraper_api_key' => 'outscraper_api_key_enc' ) as $post => $option ) { $value = isset( $_POST[ $post ] ) ? trim( wp_unslash( $_POST[ $post ] ) ) : ''; if ( '' !== $value ) { $encrypted = CGR_Crypto::encrypt( $value ); if ( is_wp_error( $encrypted ) ) { $this->redirect( 'cgr-sources', 'error', $encrypted->get_error_message(), array( 'location' => $location_id ) ); } $changes[ $option ] = $encrypted; } }
		$this->api->update_location( $location_id, array_merge( $current, $changes ) );
		$this->redirect( 'cgr-sources', 'success', __( 'Location source settings and synchronization schedule saved.', 'calico-google-reviews' ), array( 'location' => $location_id ) );
	}

	public function add_location() { $this->authorize( 'cgr_add_location' ); $name = isset( $_POST['location_name'] ) ? sanitize_text_field( wp_unslash( $_POST['location_name'] ) ) : ''; if ( '' === trim( $name ) ) { $this->redirect( 'cgr-sources', 'error', __( 'Enter a location name.', 'calico-google-reviews' ) ); } $id = $this->api->create_location( $name ); $this->redirect( 'cgr-sources', 'success', __( 'Location added. Configure its review sources below.', 'calico-google-reviews' ), array( 'location' => $id ) ); }
	public function delete_location() { $this->authorize( 'cgr_delete_location' ); $id = isset( $_POST['location_id'] ) ? sanitize_key( wp_unslash( $_POST['location_id'] ) ) : ''; $result = $this->api->delete_location( $id ); if ( is_wp_error( $result ) ) { $this->redirect( 'cgr-sources', 'error', $result->get_error_message(), array( 'location' => $id ) ); } $this->redirect( 'cgr-sources', 'success', __( 'Location profile deleted. Stored reviews were kept.', 'calico-google-reviews' ), array( 'location' => $this->api->get_default_location_id() ) ); }

	public function add_review() { $this->authorize( 'cgr_add_review' ); $location_id = isset( $_POST['location_id'] ) ? sanitize_key( wp_unslash( $_POST['location_id'] ) ) : ''; $this->result_redirect( $this->importer->import_manual( wp_unslash( $_POST ), $location_id ), 'cgr-import', __( 'Review saved.', 'calico-google-reviews' ) ); }
	public function import_csv() { $this->authorize( 'cgr_import_csv' ); if ( empty( $_FILES['reviews_csv']['tmp_name'] ) || ! empty( $_FILES['reviews_csv']['error'] ) || (int) $_FILES['reviews_csv']['size'] > 50 * MB_IN_BYTES ) { $this->redirect( 'cgr-import', 'error', __( 'Choose a valid CSV file smaller than 50 MB.', 'calico-google-reviews' ) ); } $name = sanitize_file_name( wp_unslash( $_FILES['reviews_csv']['name'] ) ); if ( 'csv' !== strtolower( pathinfo( $name, PATHINFO_EXTENSION ) ) ) { $this->redirect( 'cgr-import', 'error', __( 'Only CSV files are accepted.', 'calico-google-reviews' ) ); } $location_id = isset( $_POST['location_id'] ) ? sanitize_key( wp_unslash( $_POST['location_id'] ) ) : ''; $this->result_redirect( $this->importer->import_csv( $_FILES['reviews_csv']['tmp_name'], $location_id ), 'cgr-import', __( 'CSV import complete.', 'calico-google-reviews' ) ); }
	public function export_reviews() { $this->authorize( 'cgr_export_reviews' ); $filename = 'calico-google-reviews-' . gmdate( 'Y-m-d' ) . '.csv'; nocache_headers(); header( 'Content-Type: text/csv; charset=utf-8' ); header( 'Content-Disposition: attachment; filename="' . $filename . '"' ); $output = fopen( 'php://output', 'w' ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fopen
		$columns = array( 'location_key', 'external_id', 'source', 'reviewer_name', 'reviewer_photo_url', 'reviewer_url', 'rating', 'review_text', 'create_time', 'update_time', 'reply_text', 'reply_update_time', 'source_url', 'last_seen_at', 'expires_at' ); fputcsv( $output, $columns ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fputcsv
		$offset = 0; do { $rows = $this->database->get_export_reviews( 500, $offset ); foreach ( $rows as $row ) { $values = array(); foreach ( $columns as $column ) { $values[] = isset( $row[ $column ] ) ? $row[ $column ] : ''; } fputcsv( $output, $values ); } $offset += count( $rows ); } while ( 500 === count( $rows ) ); // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fputcsv
		fclose( $output ); exit; // phpcs:ignore WordPress.WP.AlternativeFunctions.file_system_operations_fclose
	}
	public function delete_reviews() { $this->authorize( 'cgr_delete_reviews' ); $ids = isset( $_POST['review_ids'] ) ? (array) $_POST['review_ids'] : array(); $count = $this->database->delete_reviews( $ids ); $this->redirect( 'cgr-reviews', 'success', sprintf( __( '%d review(s) deleted.', 'calico-google-reviews' ), $count ) ); }
	public function delete_all_reviews() { $this->authorize( 'cgr_delete_all_reviews' ); $count = $this->database->delete_all_reviews(); $this->redirect( 'cgr-reviews', 'success', sprintf( __( '%d review(s) permanently deleted.', 'calico-google-reviews' ), $count ) ); }
	public function remove_duplicates() { $this->authorize( 'cgr_remove_duplicates' ); $result = $this->database->remove_duplicates(); $this->redirect( 'cgr-reviews', 'success', sprintf( __( '%d duplicate review(s) removed; the most complete copies were kept.', 'calico-google-reviews' ), $result['removed'] ) ); }
	public function sync_place() { $this->authorize( 'cgr_sync_place' ); $id = $this->posted_location_id(); $this->result_redirect( $this->sync->collect_place_reviews( $id ), 'cgr-sources', __( 'Google Places API collection complete.', 'calico-google-reviews' ), array( 'location' => $id ) ); }
	public function sync_outscraper() { $this->authorize( 'cgr_sync_outscraper' ); $id = $this->posted_location_id(); $this->result_redirect( $this->sync->run_outscraper_sync( $id ), 'cgr-sources', __( 'Outscraper API import complete.', 'calico-google-reviews' ), array( 'location' => $id ) ); }
	public function test_place() { $this->authorize( 'cgr_test_place' ); $id = $this->posted_location_id(); $place = $this->api->fetch_place( $id ); if ( is_wp_error( $place ) ) { $this->redirect( 'cgr-sources', 'error', $place->get_error_message(), array( 'location' => $id ) ); } $this->redirect( 'cgr-sources', 'success', sprintf( __( 'Connected to %s.', 'calico-google-reviews' ), isset( $place['displayName']['text'] ) ? $place['displayName']['text'] : __( 'Google place', 'calico-google-reviews' ) ), array( 'location' => $id ) ); }

	private function action_form( $action, $label, $primary = false, array $fields = array(), $confirmation = '' ) { ?><form method="post" action="<?php echo esc_url( admin_url( 'admin-post.php' ) ); ?>"><input type="hidden" name="action" value="<?php echo esc_attr( $action ); ?>"><?php foreach ( $fields as $name => $value ) : ?><input type="hidden" name="<?php echo esc_attr( $name ); ?>" value="<?php echo esc_attr( $value ); ?>"><?php endforeach; ?><?php wp_nonce_field( $action ); ?><button class="button <?php echo $primary ? 'button-primary' : ''; ?>"<?php if ( $confirmation ) : ?> onclick="return confirm('<?php echo esc_js( $confirmation ); ?>')"<?php endif; ?>><?php echo esc_html( $label ); ?></button></form><?php }
	private function posted_location_id() { return isset( $_POST['location_id'] ) ? sanitize_key( wp_unslash( $_POST['location_id'] ) ) : $this->api->get_default_location_id(); }
	private function source_label( $source ) { $labels = array( 'places' => __( 'Google Places API', 'calico-google-reviews' ), 'outscraper' => __( 'Outscraper API', 'calico-google-reviews' ), 'business' => __( 'Legacy Business Profile', 'calico-google-reviews' ), 'csv' => __( 'CSV', 'calico-google-reviews' ), 'manual' => __( 'Manual', 'calico-google-reviews' ) ); return isset( $labels[ $source ] ) ? $labels[ $source ] : ucfirst( $source ); }
	private function authorize( $action ) { $this->guard(); check_admin_referer( $action ); }
	private function guard() { if ( ! current_user_can( 'manage_options' ) ) { wp_die( esc_html__( 'You do not have permission to manage reviews.', 'calico-google-reviews' ) ); } }
	private function result_redirect( $result, $page, $success, array $extra = array() ) { if ( is_wp_error( $result ) ) { $this->redirect( $page, 'error', $result->get_error_message(), $extra ); } if ( is_array( $result ) && isset( $result['imported'] ) ) { $success .= ' ' . sprintf( __( '%1$d new; %2$d duplicate or invalid rows skipped.', 'calico-google-reviews' ), $result['imported'], $result['skipped'] ); } $this->redirect( $page, 'success', $success, $extra ); }
	private function redirect( $page, $type, $message, array $extra = array() ) { wp_safe_redirect( add_query_arg( array_merge( array( 'page' => $page, 'cgr_notice' => rawurlencode( $message ), 'cgr_type' => 'error' === $type ? 'error' : 'success' ), $extra ), admin_url( 'admin.php' ) ) ); exit; }
	private function header( $title, $description ) { ?><div class="wrap cgr-admin"><h1><?php echo esc_html( $title ); ?></h1><p class="description"><?php echo esc_html( $description ); ?></p><?php $this->notice(); }
	private function footer() { ?></div><?php }
	private function notice() { if ( ! empty( $_GET['cgr_notice'] ) ) { $type = isset( $_GET['cgr_type'] ) && 'error' === sanitize_key( wp_unslash( $_GET['cgr_type'] ) ) ? 'error' : 'success'; echo '<div class="notice notice-' . esc_attr( $type ) . ' is-dismissible"><p>' . esc_html( sanitize_text_field( rawurldecode( wp_unslash( $_GET['cgr_notice'] ) ) ) ) . '</p></div>'; } }
}
